def order_tasks(tasks):
    seen = {}
    for t in tasks:
        tid = t["id"]
        if tid in seen:
            raise ValueError(f"duplicate task id: {tid}")
        seen[tid] = len(seen)

    indeg = {tid: 0 for tid in seen}
    adj = {tid: [] for tid in seen}
    for t in tasks:
        tid = t["id"]
        deps = t.get("depends_on") or []
        for d in set(deps):
            if d == tid:
                raise ValueError(f"self dependency: {tid}")
            if d not in seen:
                raise ValueError(f"unknown dependency: {d}")
            adj[d].append(tid)
            indeg[tid] += 1

    n = len(seen)
    order = []
    ready = [i for i, tid in enumerate(seen) if indeg[tid] == 0]
    ready.sort()
    pos = 0
    while pos < len(ready):
        tid = ready[pos]
        pos += 1
        order.append(tid)
        newly = []
        for nxt in adj[tid]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                newly.append(nxt)
        if newly:
            ready.extend(newly)
            ready.sort()

    if len(order) != n:
        raise ValueError("cycle detected")
    return order
