'use strict';

function createAsyncCache(load, ttlMs, now = Date.now) {
  const cache = new Map(); // key -> { value, expiresAt }
  const inflight = new Map(); // key -> { promise, settled, expiresAt, hasValue }

  function get(key) {
    const cached = cache.get(key);
    if (cached && now() < cached.expiresAt) {
      return Promise.resolve(cached.value);
    }
    // Drop stale entry.
    if (cached) cache.delete(key);

    const existing = inflight.get(key);
    if (existing) {
      return existing.promise;
    }

    let resolveFn;
    let rejectFn;
    const state = {
      settled: false,
      expiresAt: null,
      hasValue: false,
      promise: new Promise((resolve, reject) => {
        resolveFn = resolve;
        rejectFn = reject;
      }),
    };
    inflight.set(key, state);

    let loaded;
    try {
      loaded = load(key);
    } catch (err) {
      // Synchronous throw: settle for current callers, do not cache.
      inflight.delete(key);
      state.settled = true;
      rejectFn(err);
      return state.promise;
    }

    if (loaded && typeof loaded.then === 'function') {
      loaded.then(
        (value) => {
          if (state.settled) return; // detached; ignore
          state.settled = true;
          state.hasValue = true;
          state.expiresAt = now() + ttlMs;
          cache.set(key, { value, expiresAt: state.expiresAt });
          inflight.delete(key);
          resolveFn(value);
        },
        (err) => {
          if (state.settled) return; // detached; ignore
          state.settled = true;
          inflight.delete(key);
          rejectFn(err);
        }
      );
    } else {
      // Synchronous return (non-thenable): treat as fulfilled.
      state.settled = true;
      state.hasValue = true;
      state.expiresAt = now() + ttlMs;
      cache.set(key, { value: loaded, expiresAt: state.expiresAt });
      inflight.delete(key);
      resolveFn(loaded);
    }

    return state.promise;
  }

  function invalidate(key) {
    cache.delete(key);
    const entry = inflight.get(key);
    if (entry) {
      // Detach: mark settled so its callbacks no longer touch cache/state,
      // but its promise still resolves/rejects for original callers.
      entry.settled = true;
      inflight.delete(key);
    }
  }

  return { get, invalidate };
}

module.exports = { createAsyncCache };
